/**
 * Draws Minecraft text as SVG pixel squares: browsers antialias and smear vector fonts, squares with `crispEdges` stay sharp
 * at any zoom. Units are game pixels, the caller scales the SVG to GUI pixels.
 */
internal object McFont {
	private const val COLUMNS = 12

	private class Glyph(val advance: Int, val rows: IntArray)

	private val glyphs by lazy {
		GLYPHS.split('|').associate { entry ->
			val (code, advance, rows) = entry.split(':')
			code.toInt().toChar() to Glyph(advance.toInt(), IntArray(8) { rows.substring(it * 3, it * 3 + 3).toInt(16) })
		}
	}

	private fun glyph(char: Char) = glyphs[char] ?: glyphs.getValue('?')

	/** Bold glyphs advance 1 px further, the game drawing them twice 1 px apart. */
	fun width(text: String, bold: Boolean = false) = text.sumOf { glyph(it).advance } + if (bold) text.length else 0

	/** The path of [text]'s pixels, each horizontal run of a glyph row merged into one rectangle. */
	fun path(text: String, bold: Boolean = false) = buildString {
		var cursor = 0
		text.forEach { char ->
			val glyph = glyph(char)
			glyph.rows.forEachIndexed { row, bits ->
				var column = 0
				while (column < COLUMNS) {
					if (bits shr column and 1 == 0) {
						column++
						continue
					}
					val start = column
					while (column < COLUMNS && bits shr column and 1 == 1) column++
					append("M${cursor + start} ${row}h${column - start}v1h${start - column}z")
				}
			}
			cursor += glyph.advance + if (bold) 1 else 0
		}
	}

	/** Splits [text] into lines at most [width] pixels wide, breaking between words like the game. */
	fun wrap(text: String, width: Int) = text.split(' ').fold(mutableListOf<String>()) { lines, word ->
		val candidate = lines.lastOrNull()?.let { "$it $word" }
		if (candidate != null && width(candidate) <= width) lines[lines.lastIndex] = candidate else lines += word
		lines
	}
}
